    const expectedOutput = new Map([
      ['the', 4],
      ['quick', 1],
      ['brown', 1],
      ['fox', 2],
      ['jumps', 1],
      ['over', 1],
      ['lazy', 1],
      ['dog', 2],
      ['barks', 1],
      ['and', 1],
      ['runs', 1],
      ['away', 1],
    ]);

